export const SUITS={fang:{name:'Fang',symbol:'▾',color:'#b95238',effect:'Bite damage'},shell:{name:'Shell',symbol:'⬟',color:'#477d83',effect:'Damage + armor'},bloom:{name:'Bloom',symbol:'✿',color:'#64894b',effect:'Damage + healing'},venom:{name:'Venom',symbol:'✦',color:'#846397',effect:'Damage + poison'}};
export const ENEMIES=[
 {name:'The Farmhand',role:'A curious passerby',hp:32,attack:5,reward:15,type:'farmhand',intent:'Swing a clumsy fist'},
 {name:'The Forager',role:'Berries, boots, bad luck',hp:48,attack:7,reward:20,type:'forager',intent:'Throw a handful of stones'},
 {name:'The Wanderer',role:'A long way from home',hp:62,attack:9,reward:25,type:'wanderer',intent:'Strike with a walking stick'},
 {name:'The Novice',role:'All courage. No armor.',hp:78,attack:11,reward:30,type:'novice',intent:'Swing a wooden sword'},
 {name:'Village Watchman',role:'Guardian of the forest road',hp:116,attack:14,reward:50,type:'watchman',intent:'Raise a shield, then strike'}
];
export const RELICS=[{id:'teeth',name:'Sharpened Splinter',description:'+2 damage from every Fang card.',symbol:'▾'},{id:'bark',name:'Bark Buckler',description:'+2 armor from every Shell card.',symbol:'⬟'},{id:'sap',name:'Sweet Sap',description:'+2 healing from every Bloom card.',symbol:'✿'},{id:'toxin',name:'Spore Pouch',description:'+1 poison from every Venom card.',symbol:'✦'},{id:'chain',name:'Lucky Button',description:'Links add ×0.35 instead of ×0.25.',symbol:'◈'}];
function random(s){s.seed=(Math.imul(s.seed,1664525)+1013904223)>>>0;return s.seed/4294967296;}
function shuffle(s,cards){for(let i=cards.length-1;i>0;i--){const j=Math.floor(random(s)*(i+1));[cards[i],cards[j]]=[cards[j],cards[i]];}return cards;}
export function newRun(seed=Date.now()){const s={version:1,seed:seed>>>0,hp:60,maxHp:60,gold:0,stage:0,turn:1,phase:'battle',relics:[],selected:[],hand:[],deck:[],discard:[],redraws:2,poison:0,log:[],enemy:null};setupBattle(s,true);return s;}
function makeDeck(){return Object.keys(SUITS).flatMap(suit=>Array.from({length:8},(_,i)=>({id:`${suit}-${i+1}`,suit,rank:i+1})));}
function setupBattle(s,tutorial=false){s.enemy={...ENEMIES[s.stage],maxHp:ENEMIES[s.stage].hp};s.turn=1;s.poison=0;s.redraws=2;s.discard=[];s.selected=[];s.deck=shuffle(s,makeDeck());s.hand=[];if(tutorial){const ids=['fang-1','fang-2','fang-3','shell-3','shell-4','bloom-4','venom-5','bloom-7'];s.hand=ids.map(id=>s.deck.find(c=>c.id===id));s.deck=s.deck.filter(c=>!ids.includes(c.id));}else draw(s);s.phase='battle';s.log=[`Encounter ${s.stage+1}: ${s.enemy.name}.`];}
function draw(s){while(s.hand.length<8){if(!s.deck.length){if(!s.discard.length)break;s.deck=shuffle(s,s.discard);s.discard=[];}s.hand.push(s.deck.pop());}}
export function links(a,b){return a.suit===b.suit||a.rank===b.rank||b.rank===a.rank+1;}
export function preview(s,ids=s.selected){if(ids.length>5||new Set(ids).size!==ids.length)throw new Error('Choose up to five different cards.');let multiplier=1,damage=0,block=0,heal=0,poison=0;const steps=[];let previous=null,chain=0,longest=0;for(const id of ids){const card=s.hand.find(c=>c.id===id);if(!card)throw new Error('Card is not in your hand.');const linked=!!previous&&links(previous,card);chain=linked?chain+1:1;longest=Math.max(longest,chain);multiplier=1+(chain-1)*(s.relics.includes('chain')?.35:.25);const base=card.suit==='fang'?card.rank+3+(s.relics.includes('teeth')?2:0):Math.ceil(card.rank/2);const hit=Math.round(base*multiplier);damage+=hit;if(card.suit==='shell')block+=card.rank+2+(s.relics.includes('bark')?2:0);if(card.suit==='bloom')heal+=Math.ceil(card.rank/2)+(s.relics.includes('sap')?2:0);if(card.suit==='venom')poison+=2+(s.relics.includes('toxin')?1:0);steps.push({...card,damage:hit,multiplier,linked});previous=card;}return {damage,block,heal,poison,longest,steps};}
export function intent(s){const boss=s.enemy.type==='watchman',guard=boss&&s.turn%2===1;return {damage:boss&&!guard?18:s.enemy.attack,guard:guard?12:0,label:guard?'Shield up · 12 armor + 14 damage':boss?'Heavy spear · 18 damage':`${s.enemy.intent} · ${s.enemy.attack} damage`};}
export function toggle(s,id){if(s.phase!=='battle')return;if(!s.hand.some(c=>c.id===id))return;const i=s.selected.indexOf(id);if(i>=0)s.selected.splice(i,1);else if(s.selected.length<5)s.selected.push(id);}
export function move(s,index,direction){if(s.phase!=='battle')return;const target=index+direction;if(index<0||target<0||index>=s.selected.length||target>=s.selected.length)return;[s.selected[index],s.selected[target]]=[s.selected[target],s.selected[index]];}
export function redraw(s){if(s.phase!=='battle'||!s.redraws||!s.selected.length)return false;const chosen=new Set(s.selected);s.discard.push(...s.hand.filter(c=>chosen.has(c.id)));s.hand=s.hand.filter(c=>!chosen.has(c.id));s.selected=[];s.redraws--;draw(s);s.log.unshift('Selected cards discarded. New cards drawn.');return true;}
function victory(s){s.gold+=s.enemy.reward;s.hp=Math.min(s.maxHp,s.hp+10);s.phase=s.stage===4?'won':'reward';s.selected=[];s.log.unshift(`Devoured ${s.enemy.name}. +${s.enemy.reward} gold, +10 health.`);}
export function attack(s){if(s.phase!=='battle'||!s.selected.length)return null;const plan=preview(s),incoming=intent(s);const hit=Math.max(0,plan.damage-incoming.guard);s.enemy.hp=Math.max(0,s.enemy.hp-hit);s.hp=Math.min(s.maxHp,s.hp+plan.heal);s.poison+=plan.poison;const chosen=new Set(s.selected);s.discard.push(...s.hand.filter(c=>chosen.has(c.id)));s.hand=s.hand.filter(c=>!chosen.has(c.id));s.selected=[];s.log.unshift(`Chain dealt ${hit} damage${incoming.guard?' after shield':''}, ${plan.block} armor, ${plan.heal} healing.`);const report={...plan,hit,incoming:0,poisonDamage:0,killed:false};if(s.enemy.hp===0){victory(s);report.killed=true;return report;}if(s.poison){report.poisonDamage=s.poison;s.enemy.hp=Math.max(0,s.enemy.hp-s.poison);s.poison=Math.max(0,s.poison-1);s.log.unshift(`Poison dealt ${report.poisonDamage} damage.`);}if(!s.enemy.hp){victory(s);report.killed=true;return report;}report.incoming=Math.max(0,incoming.damage-plan.block);s.hp=Math.max(0,s.hp-report.incoming);s.log.unshift(`${s.enemy.name} dealt ${report.incoming} damage.`);if(!s.hp)s.phase='lost';else{s.turn++;draw(s);}s.log=s.log.slice(0,12);return report;}
export function chooseReward(s,id){if(s.phase!=='reward')return false;if(id==='rest')s.hp=Math.min(s.maxHp,s.hp+15);else{if(!RELICS.some(r=>r.id===id)||s.relics.includes(id))return false;s.relics.push(id);}s.stage++;setupBattle(s);return true;}
export function restore(value){if(!value||value.version!==1||!['battle','reward','won','lost'].includes(value.phase)||!Number.isInteger(value.stage)||value.stage<0||value.stage>4||!Number.isInteger(value.turn)||value.turn<1||!Number.isFinite(value.hp)||value.hp<0||value.hp>60||value.maxHp!==60||!Array.isArray(value.relics)||value.relics.some(id=>!RELICS.some(r=>r.id===id))||!Array.isArray(value.selected)||value.selected.length>5)return null;const cards=[...makeDeck()],valid=c=>c&&cards.some(x=>x.id===c.id&&x.rank===c.rank&&x.suit===c.suit);for(const key of ['hand','deck','discard'])if(!Array.isArray(value[key])||!value[key].every(valid))return null;const all=[...value.hand,...value.deck,...value.discard];if(all.length!==32||new Set(all.map(c=>c.id)).size!==32||value.hand.length>8||new Set(value.selected).size!==value.selected.length||!value.selected.every(id=>value.hand.some(c=>c.id===id)))return null;const enemy=ENEMIES[value.stage];if(!value.enemy||value.enemy.type!==enemy.type||!Number.isFinite(value.enemy.hp)||value.enemy.hp<0||value.enemy.hp>enemy.hp||!Number.isInteger(value.redraws)||value.redraws<0||value.redraws>2||!Number.isFinite(value.poison)||value.poison<0||!Number.isFinite(value.gold)||value.gold<0||!Number.isFinite(value.seed))return null;return {...value,enemy:{...enemy,maxHp:enemy.hp,hp:value.enemy.hp},log:Array.isArray(value.log)?value.log.filter(x=>typeof x==='string').slice(0,12):[]};}
